package com.ejemplo.alquileres.seeder;
import com.ejemplo.alquileres.model.*; import com.ejemplo.alquileres.repository.*; import java.math.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Component;
/** Datos idempotentes del perfil dev: seis meses de cobros para el dashboard. */
@Component public class HistoriaDashboardSeeder {private final ContratoRepository contratos;private final PagoRepository pagos;private final InmuebleRepository inmuebles;private final PersonaRepository personas;private final Clock clock;public HistoriaDashboardSeeder(ContratoRepository c,PagoRepository p,InmuebleRepository i,PersonaRepository q,Clock k){contratos=c;pagos=p;inmuebles=i;personas=q;clock=k;}public void cargar(){if(contratos.count()>0)return;List<Inmueble> is=inmuebles.findAll().stream().filter(i->i.getEstado()==EstadoInmueble.DISPONIBLE).limit(4).toList();List<Persona> ps=personas.findAll().stream().filter(Persona::isActivo).limit(4).toList();LocalDate hoy=LocalDate.now(clock);for(int n=0;n<Math.min(is.size(),ps.size());n++){Inmueble i=is.get(n);Persona a=ps.get(n);BigDecimal renta=BigDecimal.valueOf(900L+n*350L).setScale(2);Contrato c=Contrato.builder().codigo("CTR-DEV-"+(n+1)).inmueble(i).arrendatario(a).fechaInicio(hoy.minusMonths(6).withDayOfMonth(1)).fechaFin(hoy.plusMonths(n==0?1:6).withDayOfMonth(hoy.plusMonths(n==0?1:6).lengthOfMonth())).diaPago(5).rentaMensual(renta).diasGracia(3).tipoMora(TipoMora.PORCENTAJE_DIARIO).valorMora(new BigDecimal("0.10")).estado(EstadoContrato.VIGENTE).fechaRegistro(hoy.minusMonths(6)).build();for(int m=0;m<8;m++){LocalDate v=c.getFechaInicio().plusMonths(m).withDayOfMonth(5);Cuota q=Cuota.builder().numero(m+1).tipo(TipoCuota.RENTA).concepto("Alquiler "+v.getMonth()).periodo(v.withDayOfMonth(1)).fechaVencimiento(v).montoCuota(renta).montoPagado(m<6? renta:BigDecimal.ZERO).estado(m<6?EstadoCuota.PAGADA:EstadoCuota.PENDIENTE).build();c.agregarCuota(q);}contratos.save(c);i.setEstado(EstadoInmueble.ALQUILADO);inmuebles.save(i);for(int m=0;m<6;m++){LocalDate f=c.getFechaInicio().plusMonths(m).withDayOfMonth(Math.min(5+m%3,fDate(c.getFechaInicio().plusMonths(m))));pagos.save(Pago.builder().serie("R001").numero((n+1)*100+m).recibo("R001-DEV-"+(n+1)+"-"+(m+1)).contrato(c).fechaPago(f).fechaRegistro(f.atTime(10,0)).medioPago(MedioPago.EFECTIVO).montoCapital(renta).montoMora(BigDecimal.ZERO).montoTotal(renta).estado(EstadoPago.EMITIDO).arrendatarioNombre(a.getNombreCompleto()).arrendatarioDocumento(a.getNumeroDocumento()).inmuebleCodigo(i.getCodigo()).inmuebleNombre(i.getNombre()).build());}}}private int fDate(LocalDate d){return d.lengthOfMonth();}}